# ------------------------------------------------------------------ extensions (more advisory depth per landing)
def _ext(slug, intro_add, guide_add, faq_add):
    e = NEW[slug]
    e['intro'] = e['intro'].replace('</p>', ' ' + intro_add + '</p>', 1) if intro_add else e['intro']
    e['guide'] += guide_add
    e['faq'] = list(e['faq']) + faq_add


